inline int16_t atan2_int(int16_t b, int16_t a)
{
	static int16_t a_abs;
	static int16_t b_abs;
	static int16_t y;

	if(a == 0 && b == 0)
	{
		return 0;
	}

	a_abs = (a < 0)?(-a):(a);
	b_abs = (b < 0)?(-b):(b);

	if(a_abs == b_abs)
	{
		if(a > 0){
			if(b > 0){
				return 1024;
			}
			else{
				return 8192 - 1024;
			}
		}
		else{
			if(b > 0){
				return 4092 - 1024;
			}
			else{
				return 4092 + 1024;
			}
		}
	}
	else if(b_abs < a_abs)
	{
		y = atan_table[b_abs * 2048 / a_abs];
		if(a > 0){
			if(b > 0){
				return y;
			}
			else{
				return 8192 - y;
			}
		}
		else{
			if(b > 0){
				return 4092 - y;
			}
			else{
				return 4092 + y;
			}
		}
	}
	else
	{
		y = atan_table[a_abs * 2048 / b_abs];
		if(a > 0){
			if(b > 0){
				return 2048 - y;
			}
			else{
				return 4096 + 2048 + y;
			}
		}
		else{
			if(b > 0){
				return 2048 + y;
			}
			else{
				return 4096 + 2048 - y;
			}
		}
	}


}



